answer:
#include <stdio.h>

void min_max(int a[], int n, int *min, int *max) {
    *min = a[0];
    *max = a[0];
    for (int i = 1; i < n; i++) {
        if (a[i] < *min) {
            *min = a[i];
        }
        if (a[i] > *max) {
            *max = a[i];
        }
    }
}

int main() {
    int a[5] = {4, 9, 1, 7, 3};
    int lo;
    int hi;
    min_max(a, 5, &lo, &hi);
    printf("%d %d\n", lo, hi);
    return 0;
}

