answer:
#include <stdio.h>

int value_or(int *p, int fallback) {
    if (p == NULL) {
        return fallback;
    }
    return *p;
}

int main() {
    int x = 7;
    printf("%d %d\n", value_or(&x, 0), value_or(NULL, -1));
    return 0;
}
